import { Component } from '@angular/core';
import { TranslateModule } from '@ngx-translate/core';
import {
  IconSearch, IconBuilding, IconTag, IconBriefcase, IconCalendarEvent,
  IconShieldCheck, IconUser, IconMail, IconPhone, IconId, IconStar, IconClock, IconWallet,
} from '@tabler/icons-angular';
import { HrmFilterPanel, HrmFilterFieldDef, HrmFilterCondition, HrmQuickFilter, HrmQuickFilterOption } from 'hrm-ui';
import { SgDoc } from '../../../doc/sg-doc';
import { SgUse, SgDo, SgDont, SgExample, SgRow } from '../../../doc/sg-blocks';

/** Doc page · Filter Panel (Data Input) — bộ lọc NÂNG CAO dạng builder: hàng trường · toán tử · giá trị,
 *  picker "Thêm điều kiện", draft → Áp dụng. Song ngữ docs.filterPanel.*. */
@Component({
  selector: 'sg-doc-filter-panel',
  imports: [TranslateModule, HrmFilterPanel, HrmQuickFilter, SgDoc, SgUse, SgDo, SgDont, SgExample, SgRow],
  template: `
    <sg-doc category="Data Input" [title]="'docs.filterPanel.title' | translate" [desc]="'docs.filterPanel.desc' | translate">

      <div sgOverview>
        <sg-row>
          <div class="tb">
            <hrm-filter-panel [label]="'docs.filterPanel.demoBtn' | translate"
              [panelTitle]="'docs.filterPanel.demoTitle' | translate"
              [panelSubtitle]="'docs.filterPanel.demoSub' | translate"
              [fields]="fields" [(conditions)]="conds"
              [resetLabel]="'docs.filterPanel.reset' | translate"
              [applyLabel]="'docs.filterPanel.apply' | translate"
              [cancelLabel]="'docs.filterPanel.cancel' | translate"
              [addLabel]="'docs.filterPanel.addCond' | translate"
              [searchPlaceholder]="'docs.filterPanel.searchCond' | translate" />
            <hrm-quick-filter [label]="'docs.filterPanel.demoQuick' | translate" mode="single"
              [options]="sorts" [(value)]="sortSel" [searchable]="false" />
          </div>
        </sg-row>
        <p class="dm-note">{{ 'docs.filterPanel.demoNote' | translate }} — {{ condsText() }}</p>
      </div>

      <div sgUsage>
        <sg-use
          [purpose]="'docs.filterPanel.purpose' | translate"
          [when]="when"
          [behavior]="'docs.filterPanel.behavior' | translate"
          [avoid]="'docs.filterPanel.avoid' | translate" />
      </div>

      <div sgBest>
        <sg-do><span [innerHTML]="'docs.filterPanel.do1' | translate"></span></sg-do>
        <sg-do><span [innerHTML]="'docs.filterPanel.do2' | translate"></span></sg-do>
        <sg-dont><span [innerHTML]="'docs.filterPanel.dont1' | translate"></span></sg-dont>
        <sg-dont><span [innerHTML]="'docs.filterPanel.dont2' | translate"></span></sg-dont>
      </div>

      <div sgExamples>
        <sg-example [title]="'docs.filterPanel.exToolbarT' | translate" [desc]="'docs.filterPanel.exToolbarD' | translate">
          <sg-row>
            <div class="tb">
              <hrm-quick-filter [label]="'docs.filterPanel.fDept' | translate" [unit]="'docs.filterPanel.fDeptUnit' | translate"
                [options]="deptOpts" [(value)]="quickDepts" />
              <hrm-quick-filter [label]="'docs.filterPanel.demoQuick' | translate" mode="single"
                [options]="sorts" [(value)]="sortSel2" [searchable]="false" />
              <hrm-filter-panel [label]="'docs.filterPanel.demoBtn' | translate"
                [panelTitle]="'docs.filterPanel.demoTitle' | translate"
                [panelSubtitle]="'docs.filterPanel.demoSub' | translate"
                [fields]="fields" [(conditions)]="conds2"
                [resetLabel]="'docs.filterPanel.reset' | translate"
                [applyLabel]="'docs.filterPanel.apply' | translate"
                [cancelLabel]="'docs.filterPanel.cancel' | translate"
                [addLabel]="'docs.filterPanel.addCond' | translate"
                [searchPlaceholder]="'docs.filterPanel.searchCond' | translate" />
            </div>
          </sg-row>
        </sg-example>
      </div>

    </sg-doc>
  `,
  styles: [`
    /* Cụm filter trên toolbar — gap 8px sát nhau (chuẩn filter group), không dùng gap 12px của sg-row. */
    .tb { display: inline-flex; flex-wrap: wrap; align-items: center; gap: 8px; }
    .dm-note { margin: 10px 0 0; font-size: var(--fs-12); color: var(--text-soft); }
  `],
})
export class SgDocFilterPanel {
  protected readonly when = ['docs.filterPanel.when1', 'docs.filterPanel.when2', 'docs.filterPanel.when3'];

  protected readonly deptOpts: HrmQuickFilterOption[] = [
    { value: 'it', label: 'Kỹ thuật' }, { value: 'biz', label: 'Kinh doanh' }, { value: 'hr', label: 'Nhân sự' },
    { value: 'acc', label: 'Kế toán' }, { value: 'mkt', label: 'Marketing' },
  ];
  protected readonly sorts: HrmQuickFilterOption[] = [
    { value: 'newest', label: 'Mới nhất' }, { value: 'oldest', label: 'Cũ nhất' }, { value: 'az', label: 'Tên A→Z' },
  ];

  /** Config lọc — như mẫu: Từ khóa (fixed) + Thường dùng + Thông tin NV + Công việc + Khác. */
  protected readonly fields: HrmFilterFieldDef[] = [
    { key: 'kw', label: 'Từ khóa', icon: IconSearch, type: 'text', fixed: true,
      placeholder: 'Nhập từ khóa (họ tên, email, mã NV...)' },
    { key: 'dept', label: 'Phòng ban', icon: IconBuilding, type: 'multi', visible: true, group: 'Thường dùng',
      options: this.deptOpts, placeholder: 'Chọn phòng ban' },
    { key: 'status', label: 'Trạng thái', icon: IconTag, type: 'multi', visible: true, group: 'Thường dùng',
      options: [
        { value: 'active', label: 'Đang làm' }, { value: 'trial', label: 'Thử việc' },
        { value: 'leave', label: 'Nghỉ phép' }, { value: 'off', label: 'Đã nghỉ' },
      ], placeholder: 'Chọn trạng thái' },
    { key: 'position', label: 'Vị trí công việc', icon: IconBriefcase, type: 'select', visible: true, group: 'Thường dùng',
      options: [
        { value: 'dev', label: 'Lập trình viên' }, { value: 'ba', label: 'BA' },
        { value: 'qa', label: 'QA' }, { value: 'pm', label: 'PM' }, { value: 'sale', label: 'Nhân viên kinh doanh' },
      ], placeholder: 'Chọn vị trí công việc' },
    { key: 'joinDate', label: 'Ngày vào', icon: IconCalendarEvent, type: 'date-range', visible: true, group: 'Thường dùng' },
    { key: 'birthday', label: 'Ngày sinh', icon: IconCalendarEvent, type: 'date-range', group: 'Thường dùng' },
    { key: 'contract', label: 'Có hợp đồng chính thức', icon: IconShieldCheck, type: 'segmented', visible: true, group: 'Công việc',
      options: [{ value: '', label: 'Tất cả' }, { value: 'yes', label: 'Có' }, { value: 'no', label: 'Không' }] },
    { key: 'name', label: 'Họ tên', icon: IconUser, type: 'text', group: 'Thông tin nhân viên' },
    { key: 'email', label: 'Email', icon: IconMail, type: 'text', group: 'Thông tin nhân viên' },
    { key: 'phone', label: 'Số điện thoại', icon: IconPhone, type: 'text', group: 'Thông tin nhân viên' },
    { key: 'code', label: 'Mã nhân viên', icon: IconId, type: 'text', group: 'Thông tin nhân viên' },
    { key: 'title', label: 'Chức danh', icon: IconBriefcase, type: 'text', group: 'Công việc' },
    { key: 'level', label: 'Cấp bậc', icon: IconBriefcase, type: 'select', group: 'Công việc',
      options: [{ value: 'staff', label: 'Nhân viên' }, { value: 'lead', label: 'Trưởng nhóm' }, { value: 'manager', label: 'Quản lý' }] },
    { key: 'manager', label: 'Quản lý trực tiếp', icon: IconUser, type: 'text', group: 'Công việc' },
    { key: 'salary', label: 'Lương cơ bản (triệu)', icon: IconWallet, type: 'number', group: 'Công việc', defaultOperator: 'between' },
    { key: 'seniority', label: 'Thâm niên (năm)', icon: IconClock, type: 'number', group: 'Công việc' },
    { key: 'score', label: 'Điểm đánh giá', icon: IconStar, type: 'select', group: 'Khác',
      options: [{ value: 'a', label: 'Xuất sắc' }, { value: 'b', label: 'Đạt' }, { value: 'c', label: 'Cần cải thiện' }] },
    { key: 'updated', label: 'Ngày cập nhật', icon: IconClock, type: 'date-range', group: 'Khác' },
  ];

  protected conds: HrmFilterCondition[] = [];
  protected conds2: HrmFilterCondition[] = [];
  protected condsText(): string {
    const c = this.conds;
    return c.length ? c.map((x) => `${x.key} ${x.operator}`).join(' · ') : '—';
  }

  protected sortSel: string[] = [];
  protected sortSel2: string[] = [];
  protected quickDepts: string[] = [];
}
